//use devtimer::DevTime;
use devtimer::run_benchmark;

fn process(inp:&String, len:usize)->i64
{
    let input = inp.as_bytes();
    let mut lastseen:Vec<u32> = vec![0;32];
    let mut last_duplicate = 0;
    for i in 1.. {
//    for i in 1..=input.len() {
            let b = (input[i-1] & 31) as usize;
        let ls = lastseen[b] as usize;
        lastseen[b] = i as u32;
        if ls > last_duplicate {
            last_duplicate = ls;
        }
        if i-last_duplicate >= len {
            return i as i64;
        }
    }
    return 0;
}

fn main() {
    let input ="
".to_owned();

    let bench_result = run_benchmark(100, |_| {
        process(&input,14);
    });
    bench_result.print_stats();

    let part2 = process(&input, 14);
    println!("part2={part2}");
}
